function D(e,d){const s=e.length;if(s<3)return e.map((t,l)=>l);const u=d*d,r=new Uint8Array(s);r[0]=1,r[s-1]=1;const h=[[0,s-1]];for(;h.length;){const[t,l]=h.pop(),x=e[t][0],c=e[t][1],a=e[l][0],g=e[l][1],o=a-x,m=g-c,k=o*o+m*m;let I=0,y=-1;for(let n=t+1;n<l;n++){let q;if(k===0){const f=e[n][0]-x,S=e[n][1]-c;q=f*f+S*S}else{let f=((e[n][0]-x)*o+(e[n][1]-c)*m)/k;f<0?f=0:f>1&&(f=1);const S=x+f*o,_=c+f*m,b=e[n][0]-S,w=e[n][1]-_;q=b*b+w*w}q>I&&(I=q,y=n)}I>u&&y>0&&(r[y]=1,h.push([t,y],[y,l]))}const i=[];for(let t=0;t<s;t++)r[t]&&i.push(t);return i}function A(e,d){const s=e.length;if(s<4)return e.map((c,a)=>a);let u=1,r=0;const h=e[0][0],i=e[0][1];for(let c=1;c<s;c++){const a=e[c][0]-h,g=e[c][1]-i,o=a*a+g*g;o>r&&(r=o,u=c)}const t=D(e.slice(0,u+1),d),l=D(e.slice(u),d),x=t.slice();for(let c=1;c<l.length;c++)x.push(u+l[c]);return x}export{D as douglasPeuckerIndices,A as simplifyRingIndices};
